1	import { ruinRules, validateRuinRules, type RuinRules } from "@pirate-sea-race/content/ruins";
2	import { drawInt, generateNavigation, generateSequence, puzzleClue, type Draw, type RuinClue, type RuinPuzzle } from "./puzzles.js";
3	
4	/** A player reading a ruin's clue, since `openedTick`. */
5	export interface RuinSession {
6	  readonly playerId: string;
7	  readonly openedTick: number;
8	}
9	
10	/** A player's lockout at one ruin: no attempt before `until`. It outlives sessions, so leaving does not clear it. */
11	export interface RuinLockout {
12	  readonly playerId: string;
13	  readonly until: number;
14	}
15	
16	export interface RuinSolve {
17	  readonly playerId: string;
18	  readonly tick: number;
19	}
20	
21	/** One regular island's ruin, guarding all of that island's sources. */
22	export interface Ruin {
23	  readonly island: number;
24	  /** The ledger's ids of the island's sources (`source-<island>-<slot>`), as the caller supplied them. */
25	  readonly sourceIds: readonly string[];
26	  /** Secret: holds the answer. Only `clueFor` may leave the server. */
27	  readonly puzzle: RuinPuzzle;
28	  /** Set by the first solve, for everyone. */
29	  readonly unlocked: boolean;
30	  /** In solve order; each player at most once. */
31	  readonly solvedBy: readonly RuinSolve[];
32	  /** Sorted by player id. */
33	  readonly lockouts: readonly RuinLockout[];
34	  /** Sorted by player id. */
