1	import { RUIN_MOVES, type RuinMove, type RuinRules, type RuinSymbol } from "@pirate-sea-race/content/ruins";
2	import { nextInt } from "../random.js";
3	
4	/**
5	 * What one tablet says about its own symbol. Positions count from 0. Every hint the generator writes is true of the
6	 * answer, and the six hints together admit exactly one sequence.
7	 *
8	 * - `absent` / `present`: the symbol is not / is in the sequence.
9	 * - `at` / `not-at`: the symbol is / is not at `position` (an absent symbol is at no position).
10	 * - `right-after` / `right-before`: both are in the sequence, the symbol immediately after / before `other`.
11	 * - `after` / `before`: both are in the sequence, the symbol somewhere after / before `other`.
12	 */
13	export type SequenceRelation =
14	  | "absent"
15	  | "present"
16	  | "at"
17	  | "not-at"
18	  | "right-after"
19	  | "right-before"
20	  | "after"
21	  | "before";
22	
23	export interface SequenceHint {
24	  readonly relation: SequenceRelation;
25	  /** The symbol the relation refers to, for the four relational hints; otherwise null. */
26	  readonly other: RuinSymbol | null;
27	  /** The position of `at` and `not-at`; otherwise null. */
28	  readonly position: number | null;
29	}
30	
31	/** A carved tablet at the site: a symbol and its hint. A sequence ruin shows one for every symbol. */
32	export interface SequenceTablet {
33	  readonly symbol: RuinSymbol;
34	  readonly hint: SequenceHint;
35	}
36	
37	export interface SequencePuzzle {
38	  readonly kind: "sequence";
39	  /** Secret: the symbols in order. */
40	  readonly answer: readonly RuinSymbol[];
41	  /** Every symbol of the rules, in the rules' fixed order, whatever the answer. */
42	  readonly tablets: readonly SequenceTablet[];
43	}
44	
45	/** A grid cell: x grows east, y grows south. */
46	export interface Cell {
47	  readonly x: number;
48	  readonly y: number;
49	}
50	
51	export interface NavigationPuzzle {
52	  readonly kind: "navigation";
53	  readonly size: number;
54	  readonly start: Cell;
55	  readonly goal: Cell;
56	  /** Sorted by row, then column. */
57	  readonly blocked: readonly Cell[];
58	  /** Secret, though a reader can work it out: the number of moves of every accepted answer. */
59	  readonly minMoves: number;
60	}
61	
62	export type RuinPuzzle = SequencePuzzle | NavigationPuzzle;
63	export type RuinKind = RuinPuzzle["kind"];
64	
65	/** The only view of a ruin a client may receive (§16): what the site shows, never the answer. */
66	export type RuinClue =
67	  | { readonly kind: "sequence"; readonly length: number; readonly tablets: readonly SequenceTablet[] }
68	  | { readonly kind: "navigation"; readonly size: number; readonly start: Cell; readonly goal: Cell; readonly blocked: readonly Cell[] };
69	
70	export type RuinAttempt =
71	  | { readonly kind: "sequence"; readonly symbols: readonly RuinSymbol[] }
72	  | { readonly kind: "navigation"; readonly moves: readonly RuinMove[] };
73	
74	/** A threaded seeded generator: each draw advances `rng`. */
75	export interface Draw {
76	  rng: number;
77	}
78	
79	/** An integer in [0, bound) from the threaded generator. */
80	export function drawInt(source: Draw, bound: number): number {
81	  const drawn = nextInt(source.rng, bound);
82	  source.rng = drawn.state;
83	  return drawn.value;
84	}
85	
86	// ---------------------------------------------------------------------------------------------------------------
87	// Sequence puzzles
88	
89	/** Whether a hint about `symbol` holds for the candidate sequence `order`. */
90	export function sequenceHintHolds(symbol: RuinSymbol, hint: SequenceHint, order: readonly RuinSymbol[]): boolean {
91	  const index = order.indexOf(symbol);
92	  const other = hint.other === null ? -1 : order.indexOf(hint.other);
93	  switch (hint.relation) {
94	    case "absent":
95	      return index < 0;
96	    case "present":
97	      return index >= 0;
98	    case "at":
99	      return index >= 0 && index === hint.position;
100	    case "not-at":
101	      return index !== hint.position;
102	    case "right-after":
103	      return index >= 0 && other >= 0 && index === other + 1;
104	    case "right-before":
105	      return index >= 0 && other >= 0 && index + 1 === other;
106	    case "after":
107	      return index >= 0 && other >= 0 && index > other;
108	    case "before":
109	      return index >= 0 && other >= 0 && index < other;
110	  }
111	}
112	
113	/** Every ordered sequence of `length` distinct symbols (120 for six symbols and three places). */
114	export function allSequences(symbols: readonly RuinSymbol[], length: number): RuinSymbol[][] {
115	  if (length === 0) return [[]];
116	  return symbols.flatMap((symbol) =>
117	    allSequences(
118	      symbols.filter((other) => other !== symbol),
119	      length - 1,
120	    ).map((rest) => [symbol, ...rest]),
121	  );
122	}
123	
124	/** The sequences every tablet's hint admits. */
125	export function sequencesMatching(tablets: readonly SequenceTablet[], symbols: readonly RuinSymbol[], length: number): RuinSymbol[][] {
126	  return allSequences(symbols, length).filter((order) => tablets.every((tablet) => sequenceHintHolds(tablet.symbol, tablet.hint, order)));
127	}
128	
129	function hint(relation: SequenceRelation, other: RuinSymbol | null = null, position: number | null = null): SequenceHint {
130	  return { relation, other, position };
131	}
132	
133	/**
134	 * The true hints a tablet may carry, repeated to weight the draw. An absent symbol mostly says so outright and
135	 * otherwise names a place it does not take; a present symbol may name its place, a neighbour or just its presence.
136	 */
137	function candidateHints(symbol: RuinSymbol, answer: readonly RuinSymbol[]): SequenceHint[] {
138	  const last = answer.length - 1;
139	  const index = answer.indexOf(symbol);
140	  if (index < 0) return [hint("absent"), hint("absent"), hint("absent"), hint("not-at", null, 0), hint("not-at", null, last)];
141	  const hints = [hint("present"), hint("at", null, index), hint("at", null, index)];
142	  for (let position = 0; position <= last; position++) if (position !== index) hints.push(hint("not-at", null, position));
143	  if (index > 0) hints.push(hint("right-after", answer[index - 1]!), hint("right-after", answer[index - 1]!));
144	  if (index < last) hints.push(hint("right-before", answer[index + 1]!), hint("right-before", answer[index + 1]!));
145	  answer.forEach((other, position) => {
146	    if (position < index) hints.push(hint("after", other));
147	    if (position > index) hints.push(hint("before", other));
148	  });
149	  return hints;
150	}
151	
152	/** Draws of the six hints before falling back to the plainest unique set. */
153	const SEQUENCE_HINT_TRIES = 200;
154	
155	/**
156	 * Deals a sequence: the answer is uniform over every ordered choice of distinct symbols, then each tablet draws a true
157	 * hint until the hints together admit only the answer. The tablets stay in the rules' symbol order, so their layout
158	 * says nothing about the answer.
159	 */
160	export function generateSequence(rules: RuinRules, source: Draw): SequencePuzzle {
161	  const pool = [...rules.symbols];
162	  const answer: RuinSymbol[] = [];
163	  for (let place = 0; place < rules.sequenceLength; place++) {
164	    const pick = drawInt(source, pool.length);
165	    answer.push(pool[pick]!);
166	    pool.splice(pick, 1);
167	  }
168	  for (let attempt = 0; attempt < SEQUENCE_HINT_TRIES; attempt++) {
169	    const tablets = rules.symbols.map((symbol) => {
170	      const hints = candidateHints(symbol, answer);
171	      return { symbol, hint: hints[drawInt(source, hints.length)]! };
172	    });
173	    if (sequencesMatching(tablets, rules.symbols, rules.sequenceLength).length === 1) return { kind: "sequence", answer, tablets };
174	  }
175	  const tablets = rules.symbols.map((symbol) => {
176	    const index = answer.indexOf(symbol);
177	    return { symbol, hint: index < 0 ? hint("absent") : hint("at", null, index) };
178	  });
179	  return { kind: "sequence", answer, tablets };
180	}
181	
182	// ---------------------------------------------------------------------------------------------------------------
183	// Navigation puzzles
184	
185	const STEPS: Readonly<Record<RuinMove, Cell>> = { N: { x: 0, y: -1 }, E: { x: 1, y: 0 }, S: { x: 0, y: 1 }, W: { x: -1, y: 0 } };
186	
187	function cellIndex(size: number, cell: Cell): number {
188	  return cell.y * size + cell.x;
189	}
190	
191	function cellAt(size: number, index: number): Cell {
192	  return { x: index % size, y: Math.floor(index / size) };
193	}
194	
195	/** Moves from start to goal over open cells, by breadth-first search; -1 when the goal cannot be reached. */
196	export function shortestPathMoves(size: number, start: Cell, goal: Cell, blocked: readonly Cell[]): number {
197	  const closed = new Set(blocked.map((cell) => cellIndex(size, cell)));
198	  if (closed.has(cellIndex(size, start)) || closed.has(cellIndex(size, goal))) return -1;
199	  const distance = new Map([[cellIndex(size, start), 0]]);
200	  const queue = [start];
201	  for (let head = 0; head < queue.length; head++) {
202	    const cell = queue[head]!;
203	    const moves = distance.get(cellIndex(size, cell))!;
204	    if (cell.x === goal.x && cell.y === goal.y) return moves;
205	    for (const move of RUIN_MOVES) {
206	      const next = { x: cell.x + STEPS[move].x, y: cell.y + STEPS[move].y };
207	      if (next.x < 0 || next.y < 0 || next.x >= size || next.y >= size) continue;
208	      const index = cellIndex(size, next);
209	      if (closed.has(index) || distance.has(index)) continue;
210	      distance.set(index, moves + 1);
211	      queue.push(next);
212	    }
213	  }
214	  return -1;
215	}
216	
217	/** Whether the moves walk from start to goal in exactly `minMoves` steps without leaving the grid or entering a block. */
218	export function walksToGoal(puzzle: NavigationPuzzle, moves: readonly RuinMove[]): boolean {
219	  if (moves.length !== puzzle.minMoves) return false;
220	  const closed = new Set(puzzle.blocked.map((cell) => cellIndex(puzzle.size, cell)));
221	  let cell = puzzle.start;
222	  for (const move of moves) {
223	    cell = { x: cell.x + STEPS[move].x, y: cell.y + STEPS[move].y };
224	    if (cell.x < 0 || cell.y < 0 || cell.x >= puzzle.size || cell.y >= puzzle.size) return false;
225	    if (closed.has(cellIndex(puzzle.size, cell))) return false;
226	  }
227	  return cell.x === puzzle.goal.x && cell.y === puzzle.goal.y;
228	}
229	
230	/** Layouts drawn before giving up; a draw outside the path bounds is simply drawn again. */
231	const NAVIGATION_TRIES = 10_000;
232	
233	/**
234	 * Deals a navigation grid: a start, a different goal and a number of blocked cells within the rules' bounds, drawn
235	 * again until the shortest path is within the rules' move bounds.
236	 */
237	export function generateNavigation(rules: RuinRules, source: Draw): NavigationPuzzle {
238	  const size = rules.gridSize;
239	  const cells = size * size;
240	  for (let attempt = 0; attempt < NAVIGATION_TRIES; attempt++) {
241	    const open = Array.from({ length: cells }, (_, index) => index);
242	    const take = () => open.splice(drawInt(source, open.length), 1)[0]!;
243	    const start = cellAt(size, take());
244	    const goal = cellAt(size, take());
245	    const count = rules.minBlockedCells + drawInt(source, rules.maxBlockedCells - rules.minBlockedCells + 1);
246	    const blocked = Array.from({ length: count }, take)
247	      .sort((a, b) => a - b)
248	      .map((index) => cellAt(size, index));
249	    const minMoves = shortestPathMoves(size, start, goal, blocked);
250	    if (minMoves >= rules.minPathMoves && minMoves <= rules.maxPathMoves) {
251	      return { kind: "navigation", size, start, goal, blocked, minMoves };
252	    }
253	  }
254	  throw new Error(`no ${size} × ${size} grid with a shortest path of ${rules.minPathMoves}–${rules.maxPathMoves} moves in ${NAVIGATION_TRIES} draws`);
255	}
256	
257	// ---------------------------------------------------------------------------------------------------------------
258	// Clues and answers
259	
260	/** The clue a player at the ruin reads. It is built field by field, so no secret can ride along. */
261	export function puzzleClue(puzzle: RuinPuzzle): RuinClue {
262	  if (puzzle.kind === "sequence") {
263	    return {
264	      kind: "sequence",
265	      length: puzzle.answer.length,
266	      tablets: puzzle.tablets.map((tablet) => ({ symbol: tablet.symbol, hint: { ...tablet.hint } })),
267	    };
268	  }
269	  return {
270	    kind: "navigation",
271	    size: puzzle.size,
272	    start: { ...puzzle.start },
273	    goal: { ...puzzle.goal },
274	    blocked: puzzle.blocked.map((cell) => ({ ...cell })),
275	  };
276	}
277	
278	/** Whether an attempt (already checked for shape) solves the puzzle. */
279	export function attemptSolves(puzzle: RuinPuzzle, attempt: RuinAttempt): boolean {
280	  if (puzzle.kind === "sequence") {
