5	 * independent 32-bit seed for each system from it with a keyed hash: HMAC-SHA-256 keyed by the secret over
6	 * `SEED_LABEL` and the system's name, of which the first four bytes (big-endian) are the seed. So no system's seed
7	 * says anything about another's, none is ever passed raw to two systems, and none depends on the public match code,
8	 * which the derivation never reads.
9	 */
10	
11	/** Bytes in a master secret: 256 bits. */
12	export const MASTER_SECRET_BYTES = 32;
13	
14	/** The versioned label every derivation hashes before the system's name. */
15	export const SEED_LABEL = "pirate-sea-race/seed/v1/";
16	
17	/**
18	 * The systems that draw a seed. `world` seeds the simulation state, `ledger` the rubbings' deal onto the sources,
19	 * `final-socket` the final island's socket, `intel` the intel module's draws; `ruins` and `fruit` are reserved for the
20	 * ruins' puzzles and the fruit deal. Each duel at sea draws `duel:<n>`, its n-th duel.
21	 */
22	export type SeedSystem = "world" | "ledger" | "final-socket" | "intel" | "ruins" | "fruit" | `duel:${number}`;
23	
24	/** A fresh master secret from `node:crypto`: the production source. */
25	export function drawMasterSecret(): Uint8Array {
26	  return new Uint8Array(randomBytes(MASTER_SECRET_BYTES));
27	}
28	
29	/** The seed of one system: HMAC-SHA-256(secret, SEED_LABEL + system), its first four bytes as an unsigned integer. */
30	export function deriveSeed(secret: Uint8Array, system: SeedSystem): number {
31	  if (secret.length < 16) throw new RangeError(`a master secret needs at least 16 bytes, got ${secret.length}`);
32	  return createHmac("sha256", secret).update(SEED_LABEL + system, "utf8").digest().readUInt32BE(0);
33	}
