21	/** A set variable's parsed value, undefined when unset or empty; a malformed one stops the server. */
22	function setting<T>(env: Readonly<Record<string, string | undefined>>, name: string, parse: (text: string) => T | undefined): T | undefined {
23	  const text = env[name];
24	  if (text === undefined || text === "") return undefined;
25	  const parsed = parse(text);
26	  if (parsed === undefined) throw new Error(`${name} is malformed: ${text}`);
