import { intelRules as defaultIntelRules, type IntelRules } from "@pirate-sea-race/content/intel";
import { matchRules as defaultMatchRules, type MatchRules } from "@pirate-sea-race/content/match";
import {
  createMatchOptionsSchema,
  DUEL_RECONNECT_SECONDS,
  DuelMessageType,
  duelReadyMessageSchema,
  JoinRefusal,
  joinMatchOptionsSchema,
  MATCH_CODE_REQUIRED_MESSAGE,
  MATCH_ROOM,
