  PROTOCOL_VERSION,
  RubbingMessageType,
  validateChooseTheftMessage,
  validateStartMatchMessage,
  type RevealMessage,
  type StartRefusedMessage,
} from "@pirate-sea-race/protocol";
import {
  addShip,
  canSee,
  createMatchState,
  defaultSimulationConfig,
  GRAPPLE_BUTTON,
  INTERACT_BUTTON,
  isWorldStep,
  NEUTRAL_INPUT,
  NOT_DOCKED,
  placeShip,
  pointInSight,
  removeShip,
  returnShip,
