} from "@pirate-sea-race/simulation";
import { createClaimState, insideTreasureCircle, stepClaim, type ClaimConfig, type ClaimEvent, type ClaimPlayer, type ClaimPoint, type ClaimState } from "@pirate-sea-race/simulation/claim";
import type { PlayerIndex } from "@pirate-sea-race/simulation/duel";
import {
  createEncounterConfig,
  createEncounterState,
