636	   * One frame of the room's clock (60 Hz). Ships sail only while the match runs (§2: player control starts after the
637	   * ready countdown and stops at the end); before and after, every helm is neutral. On every third frame the world
638	   * tick runs in §5's order (`worldTick`), and a fault inside it aborts the match (§12).
639	   */
640	  private advance(): void {
641	    if (this.paused) return;
642	    const frame = this.simulation.frame + 1;
643	    const inputs: Record<string, PlayerInput> = {};
644	    const playing = this.inPlay();
645	    const held = this.heldPlayers();
646	    for (const [sessionId, gate] of this.gates) {
647	      // No control before the start or after the end; a reserved or respawning ship ignores its player's helm (§6).
648	      if (!playing || held.has(sessionId)) inputs[sessionId] = NEUTRAL_INPUT;
649	      // A lapsed client gets no entry: its ship sails as neutral, but keeps its mooring throttle until real input.
650	      else if (!gate.lapsedAt(frame)) inputs[sessionId] = gate.inputAt(frame);
651	    }
652	    this.simulation = step(this.config, this.simulation, inputs);
653	    for (const duel of this.seaDuels.values()) duel.machine.advance();
654	    if (!isWorldStep(this.simulation.frame)) return;
655	    const tick = this.simulation.worldTick;
656	    try {
657	      this.worldTick(frame, tick, held, playing);
658	    } catch (error) {
659	      this.fault(tick, error);
660	    }
661	    for (const gate of this.gates.values()) gate.worldStepTaken();
662	    this.checkInvariants(tick);
663	    this.mirror();
664	    if (this.pauseAt !== undefined && tick >= this.pauseAt) {
665	      this.pauseAt = undefined;
666	      this.paused = true;
667	    }
668	  }
669	
670	  /**
671	   * One world tick (20 Hz), in a fixed order. While the match runs: the ledger's clock (closed theft windows settle),
672	   * the §12 timers, then §5's order: the encounters (accepted reservations first), the ledger's holds, the claim
673	   * channel, the match flow (with this tick's claim end and accomplishments), and the reveals. Before control start
674	   * only the timers and the flow run (the lobby and the ready countdown); once the match has ended nothing changes but
675	   * the settled duels' lobbies leaving their fighters' views.
676	   */
677	  private worldTick(frame: number, tick: number, held: ReadonlySet<string>, playing: boolean): void {
678	    if (this.flow.end !== null) {
679	      this.closeShownDuels(tick);
680	      return;
681	    }
682	    if (this.faultNext) {
683	      this.faultNext = false;
684	      throw new Error("test-only fault injected into the world tick");
685	    }
686	    // The ledger's clock first: choice windows that closed settle with the default theft.
687	    this.ledgerStep("advanceLedger", advanceLedger(this.ledger, { tick }));
688	    this.runAbsences(tick);
689	    let claimEnd: FlowReport | undefined;
690	    if (playing) {
691	      this.stepEncounters(frame, held);
692	      this.stepChannels(frame, tick);
693	      claimEnd = this.stepClaim(frame, tick);
694	    }
695	    this.noteSettlements();
696	    if (playing) this.reportAccomplishments(tick);
697	    this.stepFlow(tick, claimEnd);
698	    if (this.flow.controlStartTick !== null && this.flow.end === null) this.stepReveals(tick);
699	  }
700	
701	  /** Player control has started and the match has not ended (§2's departure and exploration). */
702	  private inPlay(): boolean {
703	    return this.flow.phase === "departure" || this.flow.phase === "exploration";
704	  }
705	
706	  /** Players whose ship is reserved for a duel (until it is settled) or waits out of the world to respawn. */
707	  private heldPlayers(): Set<string> {
708	    const held = new Set<string>();
709	    for (const duel of this.encounters.duels) for (const id of duel.players) held.add(id);
710	    for (const player of this.encounters.players) if (player.respawn !== null) held.add(player.id);
711	    return held;
712	  }
713	
714	  /** The duel at sea a session fights in (until its lobby is removed). */
715	  private duelOfSession(sessionId: string): SeaDuel | undefined {
716	    for (const duel of this.seaDuels.values()) if (duel.players.includes(sessionId)) return duel;
717	    return undefined;
718	  }
719	
720	  /** Takes a settled duel's lobby out of its fighters' views. */
721	  private closeSeaDuel(duel: SeaDuel): void {
722	    this.state.duels.delete(duel.key);
723	    this.seaDuels.delete(duel.id);
724	  }
725	
726	  /**
727	   * §12 on the world tick: a fighter away from an unfinished duel for `duelAbsenceTicks` forfeits it (the duel goes on
728	   * to its settlement; they keep their seat); a disconnected player whose reservation deadline has come is removed,
729	   * their remaining rubbings going into a cache at the respawn dock the encounter rules would choose.
730	   */
731	  private runAbsences(tick: number): void {
732	    for (const [id, away] of this.away) {
733	      if (away.duelAbsentSince === undefined) continue;
734	      const duel = this.duelOfSession(id);
735	      if (duel === undefined || duel.machine.outcome !== undefined) away.duelAbsentSince = undefined;
736	      else if (tick - away.duelAbsentSince >= this.tuning.duelAbsenceTicks) {
737	        duel.machine.leave(id);
738	        away.duelAbsentSince = undefined;
739	      }
740	    }
741	    for (const player of this.ledger.players) {
742	      if (player.status !== "disconnected" || player.reservationDeadline === null || tick < player.reservationDeadline) continue;
743	      const position = this.respawnDockOf(player.id);
744	      this.ledgerStep("expireReservation", expireReservation(this.ledger, { playerId: player.id, tick, position }));
745	      // §12: an expired reservation releases the seat, which the flow counts as leaving.
746	      this.flowReports.push({ kind: "leave", playerId: player.id });
747	      const duel = this.duelOfSession(player.id);
748	      if (duel !== undefined && duel.machine.outcome === undefined) duel.machine.leave(player.id);
749	      const away = this.away.get(player.id);
750	      this.removePlayer(player.id);
751	      // The socket's seat goes too: Colyseus then calls onLeave, which finds the player already gone.
752	      if (typeof away?.reconnection?.reject === "function") away.reconnection.reject(false);
753	    }
754	  }
755	
756	  /** §12 expiry: the dock the encounter rules would respawn this player at, from where their ship is (or waits). */
757	  private respawnDockOf(id: string): { x: number; y: number } {
758	    const ship = this.simulation.ships.find((each) => each.id === id);
759	    const respawn = this.encounters.players.find((each) => each.id === id)?.respawn ?? null;
760	    const from = respawn !== null ? { x: respawn.x, y: respawn.y } : ship !== undefined ? { x: ship.x, y: ship.y } : dockCentre(this.config.map, 0);
761	    const waiting = new Set(this.encounters.players.filter((each) => each.respawn !== null).map((each) => each.id));
762	    const opponents = this.simulation.ships.filter((each) => each.id !== id && !waiting.has(each.id)).map((each) => ({ x: each.x, y: each.y }));
763	    const point = this.encounterConfig.modes.ship.rules.respawnPoint({ encounter: from, own: from, opponents, clearRadius: this.encounterConfig.respawnClearRadius });
764	    return { x: point.x, y: point.y };
765	  }
766	
767	  /** §12 quit: a duel in progress is forfeited (in the ledger and in the fight), the rest goes to the nearest dock. */
768	  private quit(id: string): void {
769	    const ship = this.simulation.ships.find((each) => each.id === id);
770	    const at = ship ?? dockCentre(this.config.map, 0);
771	    const position = dockCentre(this.config.map, nearestDockBySea(this.config.map, at.x, at.y));
772	    this.ledgerStep("quitPlayer", quitPlayer(this.ledger, { playerId: id, tick: this.simulation.worldTick, position }));
773	    const duel = this.duelOfSession(id);
774	    if (duel !== undefined && duel.machine.outcome === undefined) duel.machine.leave(id);
775	  }
776	
777	  /** The ship and the input channel of a player who has left the ledger's match. */
778	  private removePlayer(id: string): void {
779	    this.simulation = removeShip(this.simulation, id);
780	    this.gates.delete(id);
781	    this.away.delete(id);
782	    this.choiceRate.delete(id);
783	  }
784	
785	  /**

